// A stub standing in for @types/titanium. It mirrors the real package's shape — a Titanium
// namespace of classes with a `Ti` alias, JSDoc on the members, and inheritance through extends
// rather than flattened — but not its size: the real index.d.ts is 2.3MB and 66k lines, and
// committing it would say nothing the resolution and host tests do not.
//
// The version in package.json is deliberately 9.2.2 while classic-project's tiapp says 12.4.0.GA,
// so a test can tell "the project's own copy won" from "the version rule picked a 12.x".

declare namespace Titanium {
	namespace UI {
		class View {
			backgroundColor: string;
			add (view: View): void;
			addEventListener (name: string, callback: () => void): void;
		}

		class Label extends View {
			/** The text to display */
			text: string;
			color: string;
		}

		class ImageView extends View {
			image: string;
		}

		class Window extends View {
			title: string;
			open (): void;
			close (): void;
		}

		/** Creates a label */
		function createLabel (options?: Partial<Label>): Label;
		function createView (options?: Partial<View>): View;
		function createImageView (options?: Partial<ImageView>): ImageView;
		function createWindow (options?: Partial<Window>): Window;
	}

	namespace App {
		const id: string;
	}
}

declare const Ti: typeof Titanium;
